{
  "schemaVersion": "0.2",
  "slug": "tree",
  "name": "Tree",
  "family": "D",
  "status": "experimental",
  "purpose": "Displays hierarchical data as an expandable and collapsible tree.",
  "scenarios": [
    "Browse a file directory",
    "Show an organization chart",
    "Navigate nested categories"
  ],
  "props": {
    "nodes": {
      "type": "string",
      "required": true,
      "description": "Array of { id, label, children? } tree nodes."
    },
    "defaultExpandedIds": {
      "type": "string",
      "required": false,
      "description": "Node ids expanded on first render."
    },
    "toggleLabel": {
      "type": "string",
      "required": false,
      "description": "Accessible label pattern for node toggles."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Tree with collapsible nodes."
    },
    {
      "name": "empty",
      "description": "No nodes provided."
    }
  ],
  "composition": {
    "allowedParents": [
      "card",
      "page",
      "drawer",
      "app-shell"
    ],
    "allowedChildren": [
      "text",
      "icon",
      "badge"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use a tree for flat lists; use List.",
    "Do not lazy-load children without a loading indicator."
  ],
  "a11y": {
    "role": "tree",
    "keyboard": [
      "Enter or Space toggles node expansion"
    ],
    "focus": "Node toggles are buttons in tab order with aria-expanded.",
    "labeling": "Each node is a treeitem labelled by its text; groups use role=group.",
    "wcag": [
      "1.3.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Indentation scales with inline direction; overflow scrolls horizontally.",
    "breakpoints": {
      "compact": "Horizontal scroll for deep levels.",
      "medium": "Default indentation.",
      "large": "Default indentation."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "tree",
    "states": [
      "default",
      "empty",
      "expanded",
      "collapsed"
    ],
    "intents": [
      "navigate-hierarchy"
    ]
  }
}

.cu-tree {
  display: block;
  color: var(--cu-color-fg-default);
  overflow-x: auto;
}

.cu-tree__level {
  list-style: none;
  margin: 0;
  padding-inline-start: var(--cu-space-3);
}

.cu-tree__row {
  display: flex;
  align-items: center;
  gap: var(--cu-space-1);
  padding-block: calc(var(--cu-space-1) / 2);
}

.cu-tree__toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--cu-space-3);
  block-size: var(--cu-space-3);
  border: 0;
  padding: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
}

.cu-tree__toggle:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
}

.cu-tree__spacer {
  inline-size: var(--cu-space-3);
}

import { useState } from 'react'
import './styles.css'

export interface TreeNode {
  id: string
  label: string
  children?: TreeNode[]
}

export interface TreeProps {
  nodes: TreeNode[]
  defaultExpandedIds?: string[]
  toggleLabel?: string
  className?: string
}

export function Tree({ nodes, defaultExpandedIds = [], toggleLabel = 'Toggle node', className }: TreeProps) {
  const [expanded, setExpanded] = useState<Set<string>>(() => new Set(defaultExpandedIds))
  const classes = ['cu-tree', className].filter(Boolean).join(' ')

  const toggle = (id: string) => {
    setExpanded((current) => {
      const next = new Set(current)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  const renderNodes = (items: TreeNode[]) => (
    <ul className="cu-tree__level" role={items === nodes ? 'tree' : 'group'}>
      {items.map((node) => {
        const hasChildren = Boolean(node.children?.length)
        const isExpanded = expanded.has(node.id)
        return (
          <li key={node.id} className="cu-tree__item" role="treeitem" aria-expanded={hasChildren ? isExpanded : undefined}>
            <div className="cu-tree__row">
              {hasChildren ? (
                <button
                  type="button"
                  className="cu-tree__toggle"
                  aria-label={`${toggleLabel}: ${node.label}`}
                  onClick={() => toggle(node.id)}
                >
                  <span aria-hidden="true">{isExpanded ? '▾' : '▸'}</span>
                </button>
              ) : (
                <span className="cu-tree__spacer" aria-hidden="true" />
              )}
              <span className="cu-tree__label">{node.label}</span>
            </div>
            {hasChildren && isExpanded ? renderNodes(node.children ?? []) : null}
          </li>
        )
      })}
    </ul>
  )

  return (
    <div className={classes} data-ai-role="tree" data-ai-intent="navigate-hierarchy" data-ai-state={nodes.length === 0 ? 'empty' : 'default'}>
      {renderNodes(nodes)}
    </div>
  )
}
